import { prepare, layout } from "./shared/layout.js";
const cache=new WeakMap();
function measure(el,size,width){const style=getComputedStyle(el),lineHeight=Math.max(size*1.28,parseFloat(style.lineHeight)||size*1.35),font=`${style.fontWeight} ${size}px ${style.fontFamily}`,key=`${font}|${el.textContent}`;let prep=cache.get(el);if(!prep||prep.key!==key){prep={key,value:prepare(el.textContent||"",font,{letterSpacing:parseFloat(style.letterSpacing)||0})};cache.set(el,prep)}return {height:layout(prep.value,width,lineHeight).height,lineHeight};}
export function fitTextPage(page,{min=12,max=24,step=.5,gap=8}={}){const content=page.querySelector(".page-content");if(!content)return{size:0,overflow:false};const nodes=[...content.querySelectorAll("p,li")].filter(e=>!e.closest(".toc-list"));if(!nodes.length)return{size:0,overflow:content.scrollHeight>content.clientHeight};const box=content.getBoundingClientRect(),cs=getComputedStyle(content),height=box.height-parseFloat(cs.paddingTop)-parseFloat(cs.paddingBottom),width=box.width-parseFloat(cs.paddingLeft)-parseFloat(cs.paddingRight);const base=nodes.map(e=>({el:e,style:getComputedStyle(e),text:e.textContent||""}));const title=content.querySelector("h1,h2,h3");let lo=min,hi=max;function fits(size){let total=0;for(const{el,style}of base){const m=measure(el,size,width);total+=m.height+parseFloat(style.marginTop||0)+parseFloat(style.marginBottom||0)}if(title){const st=getComputedStyle(title),m=measure(title,Math.min(size+6,30),width);total+=m.height+parseFloat(st.marginTop||0)+parseFloat(st.marginBottom||0)}return total+gap<=height}for(let i=0;i<7;i++){let mid=Math.round((lo+hi)*2)/4;if(fits(mid))lo=mid;else hi=mid}if(title)title.style.fontSize=`${lo+6}px`;for(const{el,style}of base){el.style.fontSize=`${lo}px`;el.style.lineHeight=`${Math.max(lo*1.28,parseFloat(style.lineHeight)||lo*1.35)}px`}page.dataset.pretextSize=String(lo);return{size:lo,overflow:!fits(lo)}}
export function fitTextBook(root){let result=[];for(const p of root.querySelectorAll(".book-page")){if(p.classList.contains("cover"))continue;result.push({page:p, ...fitTextPage(p,{min:p.classList.contains("pdf-leaf")?12:14,max:21})})}return result}
